// ---- Security: clean everything that is loaded from storage, a backup file or the cloud ----
function sanitizeState(x,k,d){d=d||0;if(d>14)return null;
 if(Array.isArray(x))return x.map(v=>sanitizeState(v,k,d+1));
 if(x&&typeof x==='object'){const o={};Object.keys(x).forEach(n=>{if(n==='__proto__'||n==='constructor'||n==='prototype')return;o[n]=sanitizeState(x[n],n,d+1)});return o}
 if(typeof x==='string'){
  if(k==='date'||k==='next'||k==='end'||k==='start')return /^\d{4}-\d{2}-\d{2}([T ][\d:.+\-Zz]*)?$/.test(x)?x:'';
  if(k==='time')return /^\d{1,2}:\d{2}(:\d{2})?$/.test(x)?x:'';
  if(k==='id'||k==='uid')return x.replace(/[^\w.~:-]/g,'').slice(0,64);
  if(k==='cur')return x.replace(/[<>&"'`]/g,'').slice(0,6)||'\u20B9'}
 return x}
