 const ms=[...Array(6)].map((_,i)=>mAdd(m,i-5)),ch=ms.map(x=>bmonth(x).n),sd=ms.map(x=>S.tx.filter(t=>t.date.startsWith(x)&&t.type==='dr').reduce((a,t)=>a+t.amount,0)),mc=Math.max(1,...ch),md=Math.max(1,...sd),lab=x=>new Date(+x.slice(0,4),+x.slice(5,7)-1,1).toLocaleDateString(undefined,{month:'short'}),up=sp?Math.round((sp-badT)/sp*100):0;
