const nextDue=(d,cy)=>{const x=new Date(d+'T12:00');if(cy==='monthly')x.setMonth(x.getMonth()+1);else if(cy==='yearly')x.setFullYear(x.getFullYear()+1);else x.setDate(x.getDate()+Number(cy));return iso(x)};
